const fs = require('fs');
const path = require('path');
const { headingId } = require('../utils/shared/headings');
const root = path.resolve(__dirname, '../..');
const contentRoot = path.join(root, 'src/content/resources');
const catalog = require('../content/resources/catalog.json');
const marker =
  '// Generated by npm run contentgen:resources. Edit the MDX and catalog, then regenerate.';
const toolComponents = {
  'debounce-throttle': 'DebounceThrottle',
  'big-o': 'BigO',
  'graph-traversal': 'GraphTraversal',
  'tree-traversal': 'TreeTraversal',
  'study-plan-builder': 'StudyPlanner',
  'pattern-quiz': 'PatternQuiz',
  'javascript-output-quiz': 'JavaScriptOutputQuiz',
  'linked-list-pointers': 'LinkedListPointers',
  'sorting-comparison': 'SortingComparison',
  'recursion-call-stack': 'RecursionStack',
  'dynamic-programming': 'DynamicProgramming',
  'edge-case-practice': 'EdgeCasePractice',
  'complexity-practice': 'ComplexityPractice',
  'spaced-review': 'SpacedReview',
  'interview-rehearsal': 'InterviewRehearsal',
  'accessible-components': 'AccessibleComponents',
};

function resourceLinks(source) {
  const prose = source.replace(/```[\s\S]*?```/g, '');
  return Array.from(prose.matchAll(/\]\(([^)]+)\)/g), (match) => match[1]);
}

function contentInfo(source) {
  let fenced = false;
  const headings = [];
  for (const line of source.split('\n')) {
    if (/^```/.test(line)) {
      fenced = !fenced;
      continue;
    }
    const match = !fenced && /^## (.+)$/.exec(line);
    if (match) {
      const title = match[1].replace(/[`*_]/g, '');
      headings.push({ title, id: headingId(title) });
    }
  }
  const words = source
    .replace(/\{\/\*[\s\S]*?\*\/\}/g, '')
    .replace(/```[\s\S]*?```/g, '')
    .replace(/<[^>]+>/g, ' ')
    .split(/\s+/)
    .filter(Boolean).length;
  return { headings, words, minutes: Math.max(1, Math.ceil(words / 220)) };
}

function syncPublicCourse() {
  const seedPath = path.join(root, 'hasura/seeds/course.json');
  // Release bundles include the generated public inventory under src. They do
  // not need the Hasura seed or any database credentials to build resources.
  if (!fs.existsSync(seedPath)) return;
  const seed = JSON.parse(fs.readFileSync(seedPath, 'utf8'));
  const metadata = Object.fromEntries(
    seed.lessons
      .filter((lesson) => lesson.status === 'ACTIVE')
      .map((lesson) => [
        lesson.slug,
        {
          title: lesson.metaTitle || lesson.title,
          description:
            lesson.metaDescription ||
            lesson.description ||
            `Study ${lesson.title.toLowerCase()} with worked examples.`,
        },
      ]),
  );
  fs.writeFileSync(
    path.join(contentRoot, 'lesson-metadata.json'),
    JSON.stringify(metadata, null, 2) + '\n',
  );
  const publicCourse = {
    categories: seed.categories.map(({ id, slug, title, position, description, previewVideo }) => ({
      id,
      slug,
      title,
      position,
      description: description || '',
      previewVideo: previewVideo || '',
    })),
    lessons: seed.lessons
      .filter((lesson) => lesson.status === 'ACTIVE')
      .map((lesson) => ({
        id: lesson.id,
        accessLevel: lesson.accessLevel,
        slug: lesson.slug,
        title: lesson.title,
        category: lesson.category,
        type: lesson.type,
        position: lesson.position,
        description:
          metadata[lesson.slug]?.description ||
          lesson.metaDescription ||
          lesson.description ||
          `Study ${lesson.title.toLowerCase()} with worked examples.`,
      })),
  };
  fs.writeFileSync(
    path.join(contentRoot, 'course.json'),
    JSON.stringify(publicCourse, null, 2) + '\n',
  );
}

function validateCatalog() {
  const ids = new Set();
  const languages = new Set(
    catalog.filter((r) => r.section === 'interview-prep').map((r) => r.slug),
  );
  for (const resource of catalog) {
    const id = `${resource.section}/${resource.slug}`;
    if (ids.has(id)) throw new Error(`Duplicate resource: ${id}`);
    ids.add(id);
    for (const part of [resource.section, resource.slug])
      if (!/^[a-z0-9-]+$/.test(part)) throw new Error(`Unsafe route: ${id}`);
    if (!resource.title || !resource.description || !/^\d{4}-\d{2}-\d{2}$/.test(resource.updated))
      throw new Error(`Incomplete metadata: ${id}`);
    for (const image of resource.images || [])
      if (
        !/^\/images\/[a-zA-Z0-9/._-]+\.(svg|png|jpe?g|webp)$/.test(image) ||
        image.includes('..') ||
        !fs.existsSync(path.join(root, 'public', image))
      )
        throw new Error(`Missing or unsafe article image ${image} in ${id}`);
    if (resource.language && !languages.has(resource.language))
      throw new Error(`Unknown language ${resource.language} in ${id}`);
    if (
      resource.languages &&
      (!Array.isArray(resource.languages) ||
        new Set(resource.languages).size !== resource.languages.length ||
        resource.languages.some((language) => !languages.has(language)))
    )
      throw new Error(`Invalid language collection in ${id}`);
    if (resource.section === 'interview-prep' && resource.language !== resource.slug)
      throw new Error(`Language guide must identify its own language: ${id}`);
  }
  return ids;
}

function generate() {
  syncPublicCourse();
  const ids = validateCatalog();
  let words = 0;
  const destinations = new Set();
  for (const resource of catalog) {
    const id = `${resource.section}/${resource.slug}`;
    const source = fs.readFileSync(path.join(contentRoot, `${id}.mdx`), 'utf8');
    const info = contentInfo(source);
    if (new Set(info.headings.map((h) => h.id)).size !== info.headings.length)
      throw new Error(`Duplicate heading IDs in ${id}`);
    for (const related of resource.related)
      if (!ids.has(related)) throw new Error(`Unknown related resource ${related} in ${id}`);
    const minimum = resource.section === 'topics' ? 400 : resource.section === 'tools' ? 650 : 950;
    if (info.words < minimum)
      throw new Error(
        `${id} has ${info.words} prose words; review its substance before publishing (minimum ${minimum}).`,
      );
    words += info.words;
    const tool = resource.section === 'tools' ? toolComponents[resource.slug] : null;
    if (resource.section === 'tools' && !tool) throw new Error(`Missing tool component for ${id}`);
    const output = `${marker}\nimport * as React from 'react';\nimport ResourcePage from 'components/pages/Resources/ResourcePage';\nimport Content from 'content/resources/${id}.mdx';\n${
      tool ? `import Tool from 'components/pages/Resources/tools/${tool}';\n` : ''
    }\nexport default function Page() {\n  return <ResourcePage resourceId=${JSON.stringify(
      id,
    )} headings={${JSON.stringify(info.headings)}} minutes={${info.minutes}}${
      tool ? ' Tool={Tool}' : ''
    }><Content /></ResourcePage>;\n}\n`;
    const destination = path.join(root, 'src/pages', `${id}.tsx`);
    destinations.add(destination);
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    fs.writeFileSync(destination, output);
  }
  removeUnpublishedRoutes(path.join(root, 'src/pages'), destinations);
  console.log(
    `Generated ${catalog.length} resource routes; ${words.toLocaleString('en-US')} prose words.`,
  );
}

function removeUnpublishedRoutes(pagesRoot, destinations) {
  for (const folder of fs
    .readdirSync(pagesRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())) {
    for (const file of fs
      .readdirSync(path.join(pagesRoot, folder.name))
      .filter((name) => name.endsWith('.tsx'))) {
      const destination = path.join(pagesRoot, folder.name, file);
      if (!destinations.has(destination) && fs.readFileSync(destination, 'utf8').startsWith(marker))
        fs.unlinkSync(destination);
    }
  }
}

if (require.main === module) generate();
module.exports = {
  generate,
  contentInfo,
  validateCatalog,
  resourceLinks,
  removeUnpublishedRoutes,
  marker,
};
